                path->aid.len = aid_len;

                memcpy(path->value, path_value, path_len);
                path->len = path_len;
        }
        else if (asn1_path[0].flags & SC_ASN1_PRESENT)   {
                /* path present: set 'path' */
                memcpy(path->value, path_value, path_len);
                path->len = path_len;
        }
