        struct sc_asn1_entry asn1_path[5];
        sc_path_t tpath = *path;

        sc_copy_asn1_entry(c_asn1_path, asn1_path);
        sc_format_asn1_entry(asn1_path + 0, (void *) &tpath.value, (void *) &tpath.len, 1);

        asn1_path[0].flags |= parent_flags;
        if (path->count > 0) {
